import{_ as C,l as A,o as e,c as i,v as r,p as n,x as E,d as s,i as m,S as l}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"SA-CCR 的 EAD","description":"","frontmatter":{"title":"SA-CCR 的 EAD","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sa-ccr-ead.md","filePath":"quant/sa-ccr-ead.md","lastUpdated":1789023840000}'),o={name:"quant/sa-ccr-ead.md"};function d(p,a,h,c,R,P){const t=A("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="sa-ccr-的-ead" tabindex="-1">SA-CCR 的 EAD <a class="header-anchor" href="#sa-ccr-的-ead" aria-label="Permalink to &quot;SA-CCR 的 EAD&quot;">​</a></h1><div class="epigraph"><p>把对手方暴露收成重置成本加潜在未来暴露，再乘一个监管给定的 α：标准化方法不模拟路径，但必须在净额集、抵押与对冲集合上把名义本金翻译成可加总的 EAD。</p><footer>—— Basel Committee, The standardised approach for measuring counterparty credit risk exposures (SA-CCR), CRE52</footer></div><p><a href="/quant/counterparty-credit">对手方与信用风险</a> 写的是随机暴露、PFE 与 CVA 的经济对象；<a href="/quant/cva-lite">CVA 要点</a> 写的是盯市价格。资本公式要的是另一个数：违约风险暴露 EAD。内部模型用 <a href="/quant/imm-eepe">EEPE</a>；标准化路径在巴塞尔换成了 SA-CCR，取代 CEM 的名义本金折扣与 SM 的久期网格。本篇只写 CRE52 把一个净额集映到</p> \\[\\mathrm{EAD}=\\alpha\\bigl(\\mathrm{RC}+\\mathrm{PFE}\\bigr) \\]<p>的会计：重置成本 RC、潜在未来暴露 PFE、乘数、监管 δ 与对冲集合。α 默认 1.4，是对错向、粒度与模型外依赖的固定加码，不是你估的 <a href="/quant/wrong-way-risk">错向风险</a>。它补的是监管暴露，不是定价引擎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CEM 按产品乘一个固定转换因子，净额只给粗糙折扣，抵押几乎不进公式：有 CSA 的互换与无抵押的远期可以拿到相近的转换暴露，催缴现实进不了资本。SM 稍细，但仍把久期与波动写成监管表，对冲集合与今日的多币种、多标的净额集对不齐。SA-CCR 要同时满足三件事：承认 ISDA 净额与合格抵押；在标准化约束下给期权、远期末期、基差一个可复现的未来暴露；让清算与非清算、有保证金与无保证金用同一套 RC / PFE 语言，只在公式分支上分叉。</p><p>EAD 进入信用风险加权资产，也进入杠杆率的暴露度量。它不是 CVA 用的风险中性 EE，也不是限额用的 PFE 分位。把 SA-CCR 的 EAD 拿去对账前台 CVA，量纲就错了：一个是监管加权的当期加附加，一个是测度下的期望损失贴现。问题是把公式的每一段对应到净额集上的可观察输入——市值 \\(V\\)、合格抵押 \\(C\\)、监管名义与到期——而不是再跑一遍蒙特卡洛。</p><h3 id="重置成本不是「当前正暴露」的别名" tabindex="-1">重置成本不是「当前正暴露」的别名 <a class="header-anchor" href="#重置成本不是「当前正暴露」的别名" aria-label="Permalink to &quot;重置成本不是「当前正暴露」的别名&quot;">​</a></h3><p>无保证金净额集：\\(\\mathrm{RC}=\\max(V-C,0)\\)。\\(V\\) 是净额集盯市，\\(C\\) 是扣过估值折扣后的净合格抵押。有保证金时还要挡住「阈值 + 最低转移额」这一条法律缝：</p> \\[\\mathrm{RC}=\\max\\bigl(V-C,\\ \\mathrm{TH}+\\mathrm{MTA}-\\mathrm{NICA},\\ 0\\bigr). \\]<p>NICA 是独立抵押（初始保证金一类）的净额。阈值与 MTA 使抵押不能连续钉住 \\(V\\)，RC 可以在 \\(V-C\\le 0\\) 时仍为正。这是对 CSA 的标准化翻译，不是内部引擎里「延迟两天 + 争议」的模拟；后者更真，但不允许写进 SA-CCR。清算头寸的变动保证金若有效，RC 往往接近零，质量转到 PFE 的保证金期因子上。</p><p><span class="marginnote">α = 1.4 对所有净额集相同。它把标准化 EAD 系统性抬高，部分替代内部模型里要对错向与集中度另估的那一层。用内部 EE 去除以 1.4 去「反推」SA-CCR 是否保守，没有定义：RC+PFE 不是 EEPE。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>PFE 不取分位数，而取监管附加再乘一个过抵押折扣：</p> \\[\\mathrm{PFE}=\\mathrm{multiplier}\\times\\mathrm{AddOn}^{\\mathrm{agg}},\\qquad \\mathrm{multiplier}=\\min\\left\\{1,\\ 0.05+0.95\\exp\\left(\\frac{V-C}{2\\times 0.95\\times\\mathrm{AddOn}^{\\mathrm{agg}}}\\right)\\right\\}. \\]<p>\\(V-C\\) 大幅为负时乘数跌向 5% 地板，承认超额抵押降低未来暴露，但不允许把 PFE 收到零——保证金期里仍可能跳出来。\\(V-C\\ge 0\\) 时乘数接近 1，附加全额计入。AddOn 按资产类别（利率、外汇、信用、股权、商品，另有其他）分别计算再<strong>相加</strong>，类别之间没有分散化：利率附加与外汇附加不能用相关抵消。这是标准化的代价，也是相对 IMM 最粗的一刀。</p><p>每一类内部才允许对冲集合。利率按币种分对冲集，集内再分三个期限桶（一年以内、一至五年、五年以上），桶内有效名义可抵，桶间给监管规定的部分抵消，再乘监管久期。外汇按货币对。信用与股权在类别内用监管相关做部分净额，同一名字的多空比跨名字更认。商品按监管商品类型分集。期权、互换期权进入时乘监管 δ（将权、价内程度、监管波动的 Black 式符号函数），使卖出期权与买入期权的附加不同号或不同量。期限因子：无保证金用到到期日的平方根缩放（有上限）；有保证金用保证金期 MPOR 的平方根，清算与非清算的 MPOR 监管取值不同。</p><h3 id="有效名义、监管-δ-与保证金期" tabindex="-1">有效名义、监管 δ 与保证金期 <a class="header-anchor" href="#有效名义、监管-δ-与保证金期" aria-label="Permalink to &quot;有效名义、监管 δ 与保证金期&quot;">​</a></h3><p>「调整名义」不是合同面值。利率与信用要用监管久期把现金流换成十年左右的风险单位；外汇与股权用名义乘即期；商品用名义乘价格。基差与波动交易有单独的名义定义，避免把名义本金当成价格风险。监管 δ 对线性工具为 ±1，对期权落在 \\((-1,1)\\)，深度虚值附加变小——这是对 CEM「期权一律按名义乘转换因子」的修正，也是对新发行奇异结构的缺口：障碍、路径依赖、缺口产品的真正 δ 不是这一张表。工程上应把每笔交易映射到（资产类、对冲集、期限桶、监管 δ、调整名义）五元组，映射表与前台产品分类要对账，漏映射会静默少计 EAD。</p><p>有保证金的 PFE 对 MPOR 极敏感。MPOR 从 10 个营业日改到 5 个，附加按平方根缩一截；争议、非日终、净额集过大时监管要求加长 MPOR。内部若用 2 日保证金期做经济 PFE、用 10 日做 SA-CCR，两套数字本来就不应接近。清算会员对 CCP 的暴露另有处理，不能把合格 CCP 的 SA-CCR 与双边 OTC 混在一张限额里当同一风险。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是<strong>把随机未来暴露压成「今天已实现的重置 + 一张监管表给出的附加」</strong>。RC 抓住已经在账上的正欠款与 CSA 缝；AddOn 抓住名义、到期、非线性与未抵消的方向；乘数抓住超额抵押对附加的折扣；α 再把整包放大。对冲只在监管承认的集合里发生：同一币种的收付息可以抵，跨币种利率在 SA-CCR 里几乎是两笔附加——经济上的汇率对冲若落在外汇类，类别间不能净。于是会出现「风险系统里是对冲、资本 EAD 接近两腿之和」。这与 <a href="/quant/simm-delta-vega">SIMM</a> 按风险类加总、类间有限相关是同一类标准化几何，参数来源不同（巴塞尔对资本，ISDA 对非清算 IM）。</p><p>乘数对 \\(V-C\\) 的指数依赖制造顺周期：市值对你有利且抵押不足时，RC 与乘数同时升，EAD 跳；市值对你不利时 RC 为零，但 AddOn 仍在，空头市值不会产生负 EAD。这是暴露的单边性，与贷款 EAD 的固定面值不同。大规模接收固定利率的净额集在利率下行时 RC 膨胀，资本占用上升，对冲要同时看 CVA 与 SA-CCR，只看一个会在资本约束下被迫砍掉经济对冲。</p><p><span class="marginnote">SA-CCR 的 PFE 不是 99% 分位。它没有概率陈述。覆盖回测应对的是内部 PFE 或 IMM，不能用「很少突破 SA-CCR」证明限额够——突破少可能只是 α 与地板乘数把数垫高了。</span></p><h3 id="与-cem、imm、杠杆率的接口" tabindex="-1">与 CEM、IMM、杠杆率的接口 <a class="header-anchor" href="#与-cem、imm、杠杆率的接口" aria-label="Permalink to &quot;与 CEM、IMM、杠杆率的接口&quot;">​</a></h3><p>相对 CEM，同一净额集在有抵押、有期限抵消时 EAD 通常下降，无抵押远期、商品与错对冲集合上可能上升——替换不是全局降资本。相对 <a href="/quant/imm-eepe">IMM EEPE</a>，SA-CCR 不能把利率与信用的错向写进路径，只能靠 α；内部模型获准时，资本 EAD 用 α×EEPE（另有压力校准），标准化法仍可能用于下限、披露或未获准的净额集。杠杆率往往直接吃 SA-CCR 或 IMM 暴露，不再乘信用风险权重，于是低权重对手方的杠杆约束可以比 RWA 更紧。实施顺序应是：法律净额集 → CSA 参数 → 产品映射 → 公式 → 再与 CVA 引擎对 \\(V\\) 与抵押，而不是先调 α。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把合同名义加总当 EAD。不要假设跨资产类对冲会降低 SA-CCR。不要用内部模型的 δ 替换监管 δ 去「更精确」——那会失去标准化的可复现性，也不被承认。结构化产品若不能映射到五类之一，会掉进「其他」或被拆腿，拆法必须事前冻结。初始保证金在 NICA 里降低 RC，但对 PFE 的乘数与 AddOn 仍在；把 IM 当成把 EAD 收到零，公式不允许。</p><p>α 不是校准盘。觉得 1.4 过严，应走 IMM 审批或压缩名义，而不是在映射里藏空头 δ。与 <a href="/quant/wrong-way-risk">错向风险</a> 的关系：特定错向（对对手方自身权益的期权、以对手方相关资产为抵押）在资本框架里往往要识别后单独从严，SA-CCR 的 α 覆盖的是一般错向的模糊加码，不能当特定错向已经处理。</p><p><span class="marginnote">同一组合的 CVA、SA-CCR EAD、SIMM IM 可以对着三套希腊字母。应对的是输入一致性（\\(V\\)、曲线、名义），不是三个输出相等。相等反而说明有一层公式被抄错了。</span></p>',31)),(e(),n(l,null,{default:E(()=>[m(t,{id:"mermaid-85",class:"mermaid",graph:"flowchart%20TD%0A%20%20NS%5B%22%E5%87%80%E9%A2%9D%E9%9B%86%3A%20V%2C%20CSA%2C%20%E5%90%8D%E4%B9%89%22%5D%20--%3E%20RC%5B%22RC%3A%20max(V-C%2C%20TH%2BMTA-NICA%2C%200)%22%5D%0A%20%20NS%20--%3E%20MAP%5B%22%E6%98%A0%E5%B0%84%3A%20%E8%B5%84%E4%BA%A7%E7%B1%BB%20%2F%20%E5%AF%B9%E5%86%B2%E9%9B%86%20%2F%20%E6%9C%9F%E9%99%90%E6%A1%B6%22%5D%0A%20%20MAP%20--%3E%20AO%5B%22%E5%90%84%E7%B1%BB%20AddOn%20%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20RC%20--%3E%20MUL%5B%22%E4%B9%98%E6%95%B0%3A%20%E8%BF%87%E6%8A%B5%E6%8A%BC%E6%8A%98%E6%89%A3%2C%20%E5%9C%B0%E6%9D%BF%205%25%22%5D%0A%20%20AO%20--%3E%20MUL%0A%20%20MUL%20--%3E%20PFE%5B%22PFE%20%3D%20%E4%B9%98%E6%95%B0%20%C3%97%20AddOn%22%5D%0A%20%20RC%20--%3E%20EAD%5B%22EAD%20%3D%20%CE%B1%20(RC%20%2B%20PFE)%22%5D%0A%20%20PFE%20--%3E%20EAD%0A%20%20EAD%20--%3E%20RWA%5B%22%E4%BF%A1%E7%94%A8%20RWA%20%2F%20%E6%9D%A0%E6%9D%86%E6%9A%B4%E9%9C%B2%22%5D%0A%20%20IMM%5B%22IMM%20EEPE%22%5D%20--%3E%20CMP%5B%22%E5%AF%B9%E7%85%A7%2C%20%E4%B8%8D%E6%98%AF%E5%90%8C%E4%B8%80%E5%AF%B9%E8%B1%A1%22%5D%0A%20%20EAD%20--%3E%20CMP%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SA-CCR（巴塞尔 CRE52）用 \\(\\mathrm{EAD}=\\alpha(\\mathrm{RC}+\\mathrm{PFE})\\) 替换 CEM/SM，α 默认 1.4。</li><li>RC 翻译当前市值与 CSA 的阈值缝；PFE 是监管附加乘过抵押乘数，不是分位暴露。</li><li>对冲只在资产类内的对冲集合与期限桶里被承认，类间附加直接相加。</li><li>有保证金时质量从 RC 转到 MPOR 驱动的附加；超额抵押不能把 PFE 收到零。</li><li>EAD 服务资本与杠杆，不替代 CVA 的 EE，也不替代内部 PFE 限额。</li><li>出处：BCBS, <em>The standardised approach for measuring counterparty credit risk exposures</em>；实施见 Basel CRE52；与内部模型对照见同一框架下的 IMM / EEPE 条款。</li></ul>',2))])}const D=C(o,[["render",d]]);export{M as __pageData,D as default};
